alter table public.reference_institutions enable row level security; alter table public.reference_programmes enable row level security; alter table public.nec_classifications enable row level security; alter table public.reference_institution_links enable row level security; alter table public.reference_programme_links enable row level security; alter table public.portal_catalog_visibility enable row level security;
drop policy if exists universities_representative_select on public.universities; drop policy if exists universities_representative_update on public.universities; drop policy if exists courses_representative_all on public.courses; drop policy if exists gallery_images_representative_all on public.gallery_images; drop policy if exists profiles_update_own on public.profiles; drop policy if exists profiles_insert_own on public.profiles;
create or replace function public.complete_inpolor_community_onboarding(p_date_of_birth date,p_locale text default 'en') returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user_id uuid:=auth.uid(); v_email text; v_existing_dob date; begin if v_user_id is null then raise exception using errcode='28000',message='Authentication is required.'; end if; if p_date_of_birth is null or p_date_of_birth>current_date-interval '18 years' or p_date_of_birth<date '1900-01-01' then raise exception using errcode='22023',message='You must be 18 or older to join INPOLOR.'; end if; if p_locale not in ('en','ms') then raise exception using errcode='22023',message='Unsupported locale.'; end if; select email into v_email from auth.users where id=v_user_id; insert into public.profiles(id,email,role,date_of_birth,preferred_locale) values(v_user_id,coalesce(v_email,''),'community_user',p_date_of_birth,p_locale) on conflict(id) do update set preferred_locale=excluded.preferred_locale,email=case when public.profiles.email='' then excluded.email else public.profiles.email end,date_of_birth=case when public.profiles.date_of_birth is null then excluded.date_of_birth else public.profiles.date_of_birth end; select date_of_birth into v_existing_dob from public.profiles where id=v_user_id; if v_existing_dob is distinct from p_date_of_birth then raise exception using errcode='22023',message='Date of birth cannot be changed.'; end if; return jsonb_build_object('profile_id',v_user_id,'onboarded',true); end; $$; revoke all on function public.complete_inpolor_community_onboarding(date,text) from public,anon; grant execute on function public.complete_inpolor_community_onboarding(date,text) to authenticated;
create or replace function public.report_inpolor_content(p_content_type text,p_content_id uuid,p_reason_code text,p_details text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_user_id uuid:=auth.uid(); begin if v_user_id is null then raise exception using errcode='28000',message='Authentication is required.'; end if; if p_content_type not in ('review','review_photo','comment','question','answer','official_response') or nullif(btrim(p_reason_code),'') is null then raise exception using errcode='22023',message='A valid report target and reason are required.'; end if; insert into public.content_reports(reporter_id,content_type,content_id,reason_code,details) values(v_user_id,p_content_type,p_content_id,btrim(p_reason_code),nullif(btrim(p_details),'')); return jsonb_build_object('status','received','message','Report received.'); end; $$; revoke all on function public.report_inpolor_content(text,uuid,text,text) from public,anon; grant execute on function public.report_inpolor_content(text,uuid,text,text) to authenticated;
create or replace function private.sync_inpolor_review_projection() returns trigger language plpgsql security definer set search_path='' as $$ declare v_course text; v_year text; v_rating numeric(3,1); v_content jsonb; v_main_experience text; begin if tg_op='DELETE' then delete from public.published_reviews where id=old.id; return old; end if; if new.status not in ('published','hidden_under_review') then delete from public.published_reviews where id=new.id; return new; end if; v_course:=btrim(coalesce(new.course_name,new.review_data->>'course','Unknown course')); v_year:=coalesce(new.study_year::text,new.review_data->>'year','Unknown year'); v_rating:=coalesce(new.overall_rating,case when coalesce(new.review_data->>'rating','')~'^[1-9]$|^10$' then (new.review_data->>'rating')::numeric else 1 end); v_content:=case when new.status='published' then coalesce(new.review_data,'{}'::jsonb) else '{}'::jsonb end; v_main_experience:=case when new.status='published' then btrim(coalesce(new.review_data->>'mainExperience',new.review_data->>'spillTheTea','')) else 'Content is under review.' end; insert into public.published_reviews(id,university_id,course,year,rating,green_flags,red_flags,spill_the_tea,vibe_tags,is_anonymous,likes_count,created_at,rating_facilities,rating_teaching,rating_class_experience,rating_safety,rating_value,rating_transport,rating_campus_life,rating_career,living_cost_monthly,content,is_complete_review,visibility_status,published_at) values(new.id,new.university_id,v_course,v_year,v_rating,case when new.status='published' then btrim(coalesce(new.review_data->>'greenFlags','')) else '' end,case when new.status='published' then btrim(coalesce(new.review_data->>'redFlags','')) else '' end,case when new.status='published' then coalesce(nullif(v_main_experience,''),'Approved review') else v_main_experience end,case when new.status='published' then coalesce(new.review_data->'vibeTags','[]'::jsonb) else '[]'::jsonb end,true,coalesce(new.likes_count,0),new.created_at,new.rating_facilities,new.rating_teaching,new.rating_class_experience,new.rating_safety,new.rating_value,new.rating_transport,new.rating_campus_life,new.rating_career,new.living_cost_monthly,v_content,new.is_complete_review,new.status,coalesce(new.published_at,new.updated_at)) on conflict(id) do update set university_id=excluded.university_id,course=excluded.course,year=excluded.year,rating=excluded.rating,green_flags=excluded.green_flags,red_flags=excluded.red_flags,spill_the_tea=excluded.spill_the_tea,vibe_tags=excluded.vibe_tags,likes_count=excluded.likes_count,rating_facilities=excluded.rating_facilities,rating_teaching=excluded.rating_teaching,rating_class_experience=excluded.rating_class_experience,rating_safety=excluded.rating_safety,rating_value=excluded.rating_value,rating_transport=excluded.rating_transport,rating_campus_life=excluded.rating_campus_life,rating_career=excluded.rating_career,living_cost_monthly=excluded.living_cost_monthly,content=excluded.content,is_complete_review=excluded.is_complete_review,visibility_status=excluded.visibility_status,published_at=excluded.published_at; return new; end; $$; revoke all on function private.sync_inpolor_review_projection() from public,anon,authenticated;
alter function public.create_parent_student_invitation(text,text,text,jsonb,jsonb,text,boolean) rename to create_parent_student_invitation_guardian_validated; revoke all on function public.create_parent_student_invitation_guardian_validated(text,text,text,jsonb,jsonb,text,boolean) from public,anon,authenticated;
create function public.create_parent_student_invitation(p_student_email text,p_preferred_location text,p_monthly_household_income text,p_parental_preferences jsonb,p_parent_preferences jsonb,p_student_age_band text,p_guardian_consent_confirmed boolean) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_parental_keys constant text[]:=array['campus_vibe','campus_concern','ultimate_win','independence']; v_parent_keys constant text[]:=array['support_style','decision_style','budget_flexibility','communication_preference']; begin if jsonb_typeof(p_parental_preferences) is distinct from 'object' or jsonb_typeof(p_parent_preferences) is distinct from 'object' or not(p_parental_preferences ?& v_parental_keys) or not(p_parent_preferences ?& v_parent_keys) or exists(select 1 from jsonb_each(p_parental_preferences) e where e.key<>all(v_parental_keys)) or exists(select 1 from jsonb_each(p_parent_preferences) e where e.key<>all(v_parent_keys)) or nullif(btrim(p_parental_preferences->>'campus_vibe'),'') is null or nullif(btrim(p_parental_preferences->>'campus_concern'),'') is null or nullif(btrim(p_parental_preferences->>'ultimate_win'),'') is null or nullif(btrim(p_parental_preferences->>'independence'),'') is null or nullif(btrim(p_parent_preferences->>'support_style'),'') is null or nullif(btrim(p_parent_preferences->>'decision_style'),'') is null or nullif(btrim(p_parent_preferences->>'budget_flexibility'),'') is null or nullif(btrim(p_parent_preferences->>'communication_preference'),'') is null then raise exception using errcode='22023',message='A complete parent profile is required.'; end if; if (p_parental_preferences->>'campus_vibe') not in ('city_campus','suburban','residential','no_preference') or (p_parental_preferences->>'campus_concern') not in ('academic_quality','safety','mental_health','industry_connections') or (p_parental_preferences->>'ultimate_win') not in ('job_ready','professional_network','leadership','international_opportunities') or (p_parental_preferences->>'independence') not in ('high_support','balanced','independent','unsure') or (p_parent_preferences->>'support_style') not in ('hands_on','check_ins','student_led','unsure') or (p_parent_preferences->>'decision_style') not in ('parent_led','shared','student_led','unsure') or (p_parent_preferences->>'budget_flexibility') not in ('strict','some_flexibility','flexible','unsure') or (p_parent_preferences->>'communication_preference') not in ('email','whatsapp','student_first','no_preference') then raise exception using errcode='22023',message='Parent preference values are invalid.'; end if; return public.create_parent_student_invitation_guardian_validated(p_student_email,p_preferred_location,p_monthly_household_income,p_parental_preferences,p_parent_preferences,p_student_age_band,p_guardian_consent_confirmed); end; $$; revoke all on function public.create_parent_student_invitation(text,text,text,jsonb,jsonb,text,boolean) from public,anon; grant execute on function public.create_parent_student_invitation(text,text,text,jsonb,jsonb,text,boolean) to authenticated;
create index if not exists reference_institution_links_university_verified_idx on public.reference_institution_links(university_id,reference_institution_id) where status='verified'; create index if not exists portal_catalog_visibility_inpolor_idx on public.portal_catalog_visibility(university_id) where portal='inpolor' and status='published'; create index if not exists published_reviews_university_visibility_idx on public.published_reviews(university_id,visibility_status,published_at desc);
